              <div style="width: 108px;text-align:center">坂本绘2</div>
            </div>
          </div>
        </div>
        <br>
      </div>
      <div>
        <div>
          文字显示：
          <br>
          <select name="fontsize" id="fontsize" class="fontselect" v-model="fontsize">
            <option value="1">显示文字</option>
            <option value="0">不显示文字</option>
          </select>
        </div>
        <div>
          <br>
          字体位置：
          <br>
          <select name="fontlocal" id="fontlocal" class="fontselect" v-model="fontloc">
            <option value="1">底部</option>
