    <div style="display:flex;background-color:#DEFFDE;height:75px;padding:15px;">
      <Button class="submitbt" @click="doSubmit" :disabled="canSubmit">{{ scbq }}</Button>
      <Button class="downloadbt" @click="doDownload" :disabled="canDownload"> 保 存 </Button>
    </div>
      
    <div style="font-size:13px;line-height: 27px;text-align: left;background-color:#DEFFDE;height:90px;padding:1px;">
