<script>
import axios from 'axios'
export default {
  name: 'HelloWorld',
  data() {
    return {
      active:'',
      active2:'',
      lihuiSelected:false,
      lihuiSelect:'坂本绘1',
      imgurl:require('../assets/default.png'),
      scbq : ' √ 生 成 表 情 ',
      canSubmit: false,
      canDownload: true,


      lihui:1,
      textInput:'',
      fontloc:1,
      font:0,
      fontsize:1,
      bgcolor:'#D0FCD0',
      fontcolor:'#222222'
    }
  },
  props: {
    msg: String
  },
  methods: {
    hoverLihui(i){
      if(i==1){
        this.active = "background-color:#78e478"
        this.active2 = "background-color:#9eef9e"
      }
      if(i==2){
        this.active2 = "background-color:#78e478"
        this.active = "background-color:#9eef9e"
      }
    },
    hoverLihuiEnd(){
      this.active = "background-color:#9eef9e"
      this.active2 = "background-color:#9eef9e"
    },
    clickLihui(i){
      this.lihuiSelected == true
      if (i == 1 || i == 2){
        this.lihui = i;
      }
      if (i == 1){
        this.lihuiSelect = "坂本绘1"
      }
      if ( i==2 ){
        this.lihuiSelect = "坂本绘2"
      }
    },
    inputingText(){
      this.textInput = event.currentTarget.value
    },


    doSubmit(){
      this.canSubmit = true;
      this.scbq = ' 生 成 中 ... '
      axios.get('http://82.156.192.64:8079/getZundaImage?text='+this.textInput+'&lihui='+this.lihui+"&fontcolor="+this.fontcolor.replace("#","")+"&bgcolor="+this.bgcolor.replace("#","")+"&font="+this.font+"&fontsize="+this.fontsize+"&fontloc="+this.fontloc, {responseType:'blob'})
      .then((resp)=>{this.imgurl = URL.createObjectURL(resp.data);this.scbq = ' √ 生 成 表 情 ';this.canDownload = false;this.canSubmit = false;}) 
    
      
    },
    doDownload(){
      const link = document.createElement('a');
      link.download = '俊达萌_'+this.textInput+'.png';
      link.href = this.imgurl;
      link.click();
      link.remove();
    }
  }
}
</script>

